165	<!-- ═══════════ EXECUTIVE BANNER ═══════════ -->
166	<div class="exec-banner">
167	  <div class="container">
168	    <h1>Biomedical Research Landscape 2024–2026:<br>Publication Trends, Topic Dynamics, and Open Access Patterns</h1>
169	    <p class="subtitle">A trend analysis of PubMed-indexed biomedical research abstracts — examining temporal publication patterns, geographic contributions, dominant and emerging research topics, open-access adoption, and collaboration intensity to inform strategic planning for research policy and funding.</p>
170	    <p class="meta">Dataset: 4,886 cleaned biomedical abstracts | PubMed | Jan 2024 – Mar 2026 | Generated: May 2026</p>
171	  </div>
172	</div>
173	
174	<div class="container">
175	
176	<!-- ═══════════ KPI BAR ═══════════ -->
177	<div class="kpi-grid">
178	  <div class="kpi-card">
179	    <div class="value" id="kpi-total">4,886</div>
180	    <div class="label">Total Publications</div>
181	    <div class="detail">2024: 3,924 | 2025: 737 | 2026: 225</div>
182	  </div>
183	  <div class="kpi-card">
184	    <div class="value" id="kpi-oa">65.1%</div>
185	    <div class="label">Open Access Rate</div>
186	    <div class="detail">Available via PubMed Central</div>
187	  </div>
188	  <div class="kpi-card">
189	    <div class="value" id="kpi-median">6.0</div>
190	    <div class="label">Median Authors per Pub</div>
191	    <div class="detail">Mean: 7.1 | Range: 1–115</div>
192	  </div>
193	  <div class="kpi-card">
194	    <div class="value" id="kpi-top10">53.7%</div>
195	    <div class="label">Top 10 Countries Share</div>
196	    <div class="detail">China + USA = 30.9% of output</div>
197	  </div>
198	  <div class="kpi-card">
199	    <div class="value" id="kpi-growth">+2.3</div>
200	    <div class="label">Top Topic Growth Rate</div>
201	    <div class="detail">Normalized rate change / 1K pubs</div>
202	  </div>
203	</div>
