[metadata] {"type": "text", "file": {"filePath": "/app/output/final_report.html", "content": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Biomedical Research Landscape 2024–2026: Publication Trends, Topic Dynamics, and Open Access Patterns</title>\n<script src=\"https://cdn.jsdelivr.net/npm/chart.js@4.4.7/dist/chart.umd.min.js\"></script>\n<style>\n  :root {\n    --bg: #f8f9fa;\n    --card-bg: #ffffff;\n    --text: #1a1a2e;\n    --text-secondary: #555;\n    --accent: #2563eb;\n    --accent-light: #dbeafe;\n    --border: #e5e7eb;\n    --green: #16a34a;\n    --red: #dc2626;\n    --amber: #d97706;\n    --max-width: 1100px;\n  }\n  * { margin: 0; padding: 0; box-sizing: border-box; }\n  body {\n    font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;\n    background: var(--bg);\n    color: var(--text);\n    line-height: 1.6;\n    font-size: 15px;\n  }\n  .container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }\n\n  /* Executive summary banner */\n  .exec-banner {\n    background: linear-gradient(135deg, #0f172a 0%, #1e3a5f 100%);\n    color: #fff;\n    padding: 48px 0 40px;\n    margin-bottom: 32px;\n  }\n  .exec-banner h1 {\n    font-size: 28px; font-weight: 700; line-height: 1.25; margin-bottom: 10px;\n  }\n  .exec-banner .subtitle {\n    font-size: 15px; opacity: 0.85; max-width: 750px;\n  }\n  .exec-banner .meta {\n    font-size: 12px; opacity: 0.6; margin-top: 20px;\n  }\n\n  /* KPI row */\n  .kpi-grid {\n    display: grid;\n    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));\n    gap: 16px;\n    margin-bottom: 32px;\n  }\n  .kpi-card {\n    background: var(--card-bg);\n    border: 1px solid var(--border);\n    border-radius: 10px;\n    padding: 20px 24px;\n    text-align: center;\n  }\n  .kpi-card .value {\n    font-size: 32px; font-weight: 700; color: var(--accent);\n  }\n  .kpi-card .label {\n    font-size: 12px; color: var(--text-secondary);\n    margin-top: 4px; text-transform: uppercase; letter-spacing: 0.5px;\n  }\n  .kpi-card .detail {\n    font-size: 11px; color: var(--text-secondary); margin-top: 4px;\n  }\n\n  /* Section */\n  .section {\n    background: var(--card-bg);\n    border: 1px solid var(--border);\n    border-radius: 12px;\n    padding: 32px;\n    margin-bottom: 24px;\n  }\n  .section h2 {\n    font-size: 20px; margin-bottom: 6px; color: var(--text);\n  }\n  .section .section-obj {\n    font-size: 13px; color: var(--text-secondary); margin-bottom: 24px;\n    font-style: italic;\n  }\n  .section h3 {\n    font-size: 16px; margin: 28px 0 10px; color: #334155;\n  }\n\n  /* Charts */\n  .chart-wrap {\n    position: relative; margin: 20px 0;\n  }\n  .chart-wrap canvas { width: 100%; }\n  .chart-row {\n    display: grid; grid-template-columns: 1fr 1fr; gap: 24px;\n  }\n  @media (max-width: 768px) { .chart-row { grid-template-columns: 1fr; } }\n\n  /* Tables */\n  table {\n    width: 100%; border-collapse: collapse; font-size: 13px; margin: 16px 0;\n  }\n  th, td {\n    text-align: left; padding: 8px 12px; border-bottom: 1px solid var(--border);\n  }\n  th {\n    font-weight: 600; color: var(--text-secondary); font-size: 11px;\n    text-transform: uppercase; letter-spacing: 0.5px; background: #f8fafc;\n  }\n  tr:hover td { background: #f8fafc; }\n  .num { text-align: right; font-variant-numeric: tabular-nums; }\n\n  /* Callout */\n  .callout {\n    background: var(--accent-light);\n    border-left: 4px solid var(--accent);\n    padding: 14px 18px; border-radius: 6px; margin: 16px 0; font-size: 14px;\n  }\n  .callout.amber {\n    background: #fef3c7; border-left-color: var(--amber);\n  }\n  .callout.green {\n    background: #dcfce7; border-left-color: var(--green);\n  }\n\n  /* Key Takeaways */\n  .takeaway-list { list-style: none; }\n  .takeaway-list li {\n    padding: 14px 0; border-bottom: 1px solid var(--border);\n    display: flex; gap: 14px; align-items: flex-start;\n  }\n  .takeaway-list li:last-child { border-bottom: none; }\n  .takeaway-num {\n    background: var(--accent); color: #fff; font-weight: 700;\n    width: 28px; height: 28px; border-radius: 50%;\n    display: flex; align-items: center; justify-content: center;\n    font-size: 13px; flex-shrink: 0; margin-top: 2px;\n  }\n  .takeaway-list .tag {\n    font-size: 10px; font-weight: 600; padding: 2px 8px; border-radius: 10px;\n    text-transform: uppercase; letter-spacing: 0.5px;\n    margin-left: 8px;\n  }\n  .tag-policy { background: #dbeafe; color: #1e40af; }\n  .tag-funding { background: #dcfce7; color: #166534; }\n  .tag-watch { background: #fef3c7; color: #92400e; }\n\n  /* Footer */\n  .footer {\n    text-align: center; font-size: 12px; color: var(--text-secondary);\n    padding: 32px 0; margin-top: 8px;\n  }\n  .data-note {\n    font-size: 12px; color: var(--text-secondary);\n    border-top: 1px solid var(--border); padding-top: 8px; margin-top: 8px;\n  }\n</style>\n</head>\n<body>\n\n<!-- ═══════════ EXECUTIVE BANNER ═══════════ -->\n<div class=\"exec-banner\">\n  <div class=\"container\">\n    <h1>Biomedical Research Landscape 2024–2026:<br>Publication Trends, Topic Dynamics, and Open Access Patterns</h1>\n    <p class=\"subtitle\">A trend analysis of PubMed-indexed biomedical research abstracts — examining temporal publication patterns, geographic contributions, dominant and emerging research topics, open-access adoption, and collaboration intensity to inform strategic planning for research policy and funding.</p>\n    <p class=\"meta\">Dataset: 4,886 cleaned biomedical abstracts | PubMed | Jan 2024 – Mar 2026 | Generated: May 2026</p>\n  </div>\n</div>\n\n<div class=\"container\">\n\n<!-- ═══════════ KPI BAR ═══════════ -->\n<div class=\"kpi-grid\">\n  <div class=\"kpi-card\">\n    <div class=\"value\" id=\"kpi-total\">4,886</div>\n    <div class=\"label\">Total Publications</div>\n    <div class=\"detail\">2024: 3,924 | 2025: 737 | 2026: 225</div>\n  </div>\n  <div class=\"kpi-card\">\n    <div class=\"value\" id=\"kpi-oa\">65.1%</div>\n    <div class=\"label\">Open Access Rate</div>\n    <div class=\"detail\">Available via PubMed Central</div>\n  </div>\n  <div class=\"kpi-card\">\n    <div class=\"value\" id=\"kpi-median\">6.0</div>\n    <div class=\"label\">Median Authors per Pub</div>\n    <div class=\"detail\">Mean: 7.1 | Range: 1–115</div>\n  </div>\n  <div class=\"kpi-card\">\n    <div class=\"value\" id=\"kpi-top10\">53.7%</div>\n    <div class=\"label\">Top 10 Countries Share</div>\n    <div class=\"detail\">China + USA = 30.9% of output</div>\n  </div>\n  <div class=\"kpi-card\">\n    <div class=\"value\" id=\"kpi-growth\">+2.3</div>\n    <div class=\"label\">Top Topic Growth Rate</div>\n    <div class=\"detail\">Normalized rate change / 1K pubs</div>\n  </div>\n</div>\n\n<!-- ═══════════ SECTION 1: PUBLICATION VOLUME ═══════════ -->\n<div class=\"section\" id=\"publication-volume-trends\">\n  <h2>1. Publication Volume &amp; Temporal Distribution</h2>\n  <p class=\"section-obj\">Monthly and yearly distribution of publications, accounting for the natural skew toward 2024 due to PubMed indexing lag. Volume trends, seasonality, and acceleration patterns are examined.</p>\n\n  <div class=\"callout amber\">\n    <strong>Data Note:</strong> Approximately 80.3% of records in this dataset are from 2024, reflecting real-world PubMed indexing patterns where older publications accumulate more indexed entries over time. The 2025 and 2026 figures represent partial-year data — 2026 covers only Q1 (Jan–Mar). All cross-year comparisons use normalized metrics. Additionally, 15.4% of records (n=754) have an unknown publication month and are excluded from monthly-level charts.\n  </div>\n\n  <div class=\"chart-row\">\n    <div class=\"chart-wrap\">\n      <h3>Publications by Year</h3>\n      <canvas id=\"chart-yearly\"></canvas>\n    </div>\n    <div class=\"chart-wrap\">\n      <h3>Monthly Publication Volume</h3>\n      <canvas id=\"chart-monthly\"></canvas>\n    </div>\n  </div>\n\n  <h3>Key Observations</h3>\n  <table>\n    <tr><th>Observation</th><th>Detail</th></tr>\n    <tr><td>Dominant 2024 volume</td><td>3,924 publications (80.3%) are from 2024. This is consistent with the known indexing lag in PubMed — more recent years have progressively fewer indexed entries.</td></tr>\n    <tr><td>Q1 2026 partial window</td><td>225 publications in 2026 cover only January–March. Extrapolating linearly, this projects to ~900 publications for full-year 2026, roughly 23% above 2025 levels — but this extrapolation should be treated cautiously given indexing lag effects.</td></tr>\n    <tr><td>Monthly seasonality</td><td>January shows the highest volume across all three years (1,746 of 4,132 records with known months), potentially reflecting year-end submission surges or journal issue scheduling patterns. Monthly volumes decline through the year in 2024 and 2025.</td></tr>\n    <tr><td>Unknown-month concentration</td><td>754 records (15.4%) lack month data. These are disproportionately from 2024 (which has higher overall volume) and may represent articles indexed without full date granularity.</td></tr>\n  </table>\n</div>\n\n<!-- ═══════════ SECTION 2: GEOGRAPHIC LANDSCAPE ═══════════ -->\n<div class=\"section\" id=\"geographic-landscape\">\n  <h2>2. Geographic Landscape of Biomedical Research</h2>\n  <p class=\"section-obj\">Top contributing countries by publication count, shifts in geographic contributions across the 2024–2026 window, and emerging or declining national research presences.</p>\n\n  <div class=\"chart-row\">\n    <div class=\"chart-wrap\">\n      <h3>Top 15 Countries by Publication Count</h3>\n      <canvas id=\"chart-countries-bar\"></canvas>\n    </div>\n    <div class=\"chart-wrap\">\n      <h3>Country Share Shift: 2024 vs 2025</h3>\n      <canvas id=\"chart-countries-shift\"></canvas>\n    </div>\n  </div>\n\n  <div class=\"chart-wrap\">\n    <h3>Open Access Rate by Country (Top 15)</h3>\n    <canvas id=\"chart-country-oa\"></canvas>\n  </div>\n\n  <h3>Key Observations</h3>\n  <table>\n    <tr><th>Observation</th><th>Detail</th></tr>\n    <tr><td>China–USA dominance</td><td>China (952, 19.5%) and the United States (521 combined, 10.7%) together account for 30.2% of all publications. India is third at 4.0%. The top 10 countries produce 53.7% of output.</td></tr>\n    <tr><td>Long tail of contributors</td><td>1,116 unique country values appear in the dataset after normalization. Many are represented by single-digit publication counts, reflecting the genuinely global nature of biomedical research.</td></tr>\n    <tr><td>Normalized 2025 shifts</td><td>When adjusted for the 2024→2025 volume decline, most countries maintain proportional representation. Countries showing relative gains in 2025 include Iran and Japan; however, small absolute numbers in 2025 mean these shifts should be interpreted cautiously.</td></tr>\n    <tr><td>OA rate variation by country</td><td>Open access rates range from ~42% to ~79% across the top 15 countries. The UK and Canada show the highest OA adoption rates, while China and Japan trend lower — reflecting differing national OA mandates and publishing cultures.</td></tr>\n    <tr><td>Country name inconsistency</td><td>The raw data contains multiple naming variants (e.g., \"USA\", \"United States\", \"US\"; \"PR China\", \"People's Republic of China\", \"China\"). These were normalized for the analysis above, reducing the effective unique count from the raw 1,126 to 1,116.</td></tr>\n  </table>\n</div>\n\n<!-- ═══════════ SECTION 3: TOPIC & MESH ANALYSIS ═══════════ -->\n<div class=\"section\" id=\"topic-and-mesh-analysis\">\n  <h2>3. Research Topic &amp; MeSH Keyword Analysis</h2>\n  <p class=\"section-obj\">Most prevalent major topics and MeSH keywords, trending and emerging research areas, and topic shifts between years.</p>\n\n  <div class=\"callout amber\">\n    <strong>Data Note:</strong> 47.1% of records (n=2,303) have an empty <code>major_topic</code> field — common for newer publications not yet MeSH-indexed. The keyword field (<code>keywords</code>) has broader coverage and is used to supplement the topic analysis. Topic growth rates are computed as the change in normalized publication rate per 1,000 publications between 2024 and 2025, accounting for the overall volume decline.\n  </div>\n\n  <div class=\"chart-row\">\n    <div class=\"chart-wrap\">\n      <h3>Top 20 Major MeSH Topics</h3>\n      <canvas id=\"chart-topics-bar\"></canvas>\n    </div>\n    <div class=\"chart-wrap\">\n      <h3>Topic Growth: Normalized Rate Change (2024→2025)</h3>\n      <canvas id=\"chart-topics-growth\"></canvas>\n    </div>\n  </div>\n\n  <h3>Fastest-Growing Keyword Clusters</h3>\n  <p style=\"font-size:13px;color:var(--text-secondary);margin-bottom:12px;\">\n    Keywords with the largest increase in normalized appearance rate (per 1,000 publications) from 2024 to 2025, filtered for keywords appearing ≥5 times in 2024.\n  </p>\n  <div class=\"chart-wrap\" style=\"max-width:700px;\">\n    <canvas id=\"chart-keywords-growth\"></canvas>\n  </div>\n\n  <h3>Top 30 Most Frequent MeSH Keywords</h3>\n  <div class=\"chart-wrap\" style=\"max-width:700px;\">\n    <canvas id=\"chart-keywords-top\"></canvas>\n  </div>\n\n  <h3>Key Observations</h3>\n  <table>\n    <tr><th>Observation</th><th>Detail</th></tr>\n    <tr><td>COVID-19 remains predominant</td><td>Despite the pandemic's acute phase ending, COVID-19 is the #1 major topic (43 publications). Its normalized rate declined from 9.4/1K (2024) to 6.8/1K (2025), suggesting gradual normalization of pandemic-related research output.</td></tr>\n    <tr><td>Chronic disease research dominates</td><td>Diabetes Mellitus Type 2, Breast Neoplasms, Alzheimer Disease, and Heart Failure rank among the top topics, reflecting the sustained research emphasis on non-communicable diseases with high global disease burden.</td></tr>\n    <tr><td>Microbiome and omics rising</td><td>Gastrointestinal Microbiome (16 publications) and MicroRNAs (11) indicate strong interest in molecular-level and systems-biology approaches. These topics are trend-sensitive and may expand further as 2025–2026 indexing catches up.</td></tr>\n    <tr><td>Coleoptera as an outlier</td><td>Coleoptera (beetles) appears as a top-10 major topic (10 publications), likely reflecting biodiversity/entomology research. Its normalized rate increased from 1.8/1K (2024) to 4.1/1K (2025) — the highest growth rate among topics with 2025 data.</td></tr>\n    <tr><td>Keyword-level growth signals</td><td>Keywords like \"Animal Structures\" (+13.1/1K), \"Animal Distribution\" (+12.7/1K), and \"Body Size\" (+10.8/1K) show outsized normalized growth, suggesting increasing biodiversity and zoological research output. \"Air Pollutants\" keywords (+8.3/1K) signal growing environmental health research. \"Molecular Dynamics Simulation\" (+5.0/1K) reflects computational methods adoption.</td></tr>\n    <tr><td>Demographic keywords dominate</td><td>\"Humans\", \"Male\", \"Female\", \"Animals\", and \"Adult\" are the most frequent MeSH keywords, consistent with the clinical and population-health orientation of PubMed-indexed research.</td></tr>\n  </table>\n</div>\n\n<!-- ═══════════ SECTION 4: OPEN ACCESS ═══════════ -->\n<div class=\"section\" id=\"open-access-patterns\">\n  <h2>4. Open Access Adoption &amp; Journal Landscape</h2>\n  <p class=\"section-obj\">Proportion of open-access vs. closed-access publications, leading journals by volume, and trends in open-access rates over time, by country, and by research type.</p>\n\n  <div class=\"chart-row\">\n    <div class=\"chart-wrap\">\n      <h3>Open Access Rate Over Time (Monthly)</h3>\n      <canvas id=\"chart-oa-monthly\"></canvas>\n    </div>\n    <div class=\"chart-wrap\">\n      <h3>Open Access by Year</h3>\n      <canvas id=\"chart-oa-yearly\"></canvas>\n    </div>\n  </div>\n\n  <div class=\"chart-row\">\n    <div class=\"chart-wrap\">\n      <h3>Open Access Rate by Research Type</h3>\n      <canvas id=\"chart-oa-type\"></canvas>\n    </div>\n    <div class=\"chart-wrap\">\n      <h3>Top 20 Journals by Volume</h3>\n      <canvas id=\"chart-journals\"></canvas>\n    </div>\n  </div>\n\n  <h3>Key Observations</h3>\n  <table>\n    <tr><th>Observation</th><th>Detail</th></tr>\n    <tr><td>Overall OA rate: 65.1%</td><td>Nearly two-thirds of publications are available via PubMed Central. This is consistent with the broader trend toward open-access publishing driven by funder mandates (e.g., Plan S, NIH Public Access Policy).</td></tr>\n    <tr><td>Temporal trend: slight upward</td><td>The OA rate rose from 64.3% (2024) to 67.0% (2025) and 71.1% (Q1 2026). The month-over-month trend shows modest but visible upward movement, consistent with gradual OA mandate expansion.</td></tr>\n    <tr><td>Preprints lead OA adoption</td><td>Preprints show the highest OA rate (~88%), which is expected since preprint servers (bioRxiv, medRxiv) are inherently open-access. Reviews and Journal Articles have comparable OA rates in the 63–68% range.</td></tr>\n    <tr><td>Journal concentration is moderate</td><td>Scientific Reports leads with 82 publications (1.7%), followed by Heliyon (76, 1.6%) and Cureus (69, 1.4%). No single journal dominates — the top 20 journals collectively account for only ~15% of publications, indicating a highly distributed publishing landscape.</td></tr>\n    <tr><td>OA rate varies by journal</td><td>Among top journals, OA rates range from 100% (e.g., bioRxiv) to below 20% for some subscription-model journals. OA-native journals (PLOS ONE, Scientific Reports) show near-universal open access.</td></tr>\n  </table>\n</div>\n\n<!-- ═══════════ SECTION 5: RESEARCH TYPE & COLLABORATION ═══════════ -->\n<div class=\"section\" id=\"research-type-collaboration\">\n  <h2>5. Research Type Distribution &amp; Collaboration Indicators</h2>\n  <p class=\"section-obj\">Breakdown by research type, author count distributions as a proxy for collaboration intensity, and variation by geography and topic.</p>\n\n  <div class=\"chart-row\">\n    <div class=\"chart-wrap\">\n      <h3>Publications by Research Type</h3>\n      <canvas id=\"chart-types\"></canvas>\n    </div>\n    <div class=\"chart-wrap\">\n      <h3>Author Count Distribution</h3>\n      <canvas id=\"chart-authors-dist\"></canvas>\n    </div>\n  </div>\n\n  <div class=\"chart-row\">\n    <div class=\"chart-wrap\">\n      <h3>Median Authors by Country (Top 15)</h3>\n      <canvas id=\"chart-authors-country\"></canvas>\n    </div>\n    <div class=\"chart-wrap\">\n      <h3>Median Authors by Year and Type</h3>\n      <canvas id=\"chart-authors-year-type\"></canvas>\n    </div>\n  </div>\n\n  <h3>Key Observations</h3>\n  <table>\n    <tr><th>Observation</th><th>Detail</th></tr>\n    <tr><td>Journal Articles dominate</td><td>71.6% of publications are classified as Journal Articles (when considering primary type). Reviews (7.5%) and Case Reports (3.8%) are the next most common types. Systematic Reviews and Preprints represent smaller but important categories.</td></tr>\n    <tr><td>Median 6 authors per paper</td><td>The median author count is 6 (mean 7.1). This is consistent with modern biomedical research norms — collaborative, often multi-institutional. 75% of publications have 9 or fewer authors; the long tail extends to 115.</td></tr>\n    <tr><td>Collaboration intensity stable</td><td>Median authors per publication has remained stable across 2024–2026 (6.0 each year). Mean authors shows minor fluctuation (7.0 → 7.3 → 6.9), likely attributable to sample composition rather than a real trend.</td></tr>\n    <tr><td>Country-level variation in team size</td><td>Median author counts range from 5 (India, Iran) to 8 (UK, Germany) across the top 15 countries. Larger teams in Western European and North American countries may reflect more multi-institutional collaboration or different disciplinary norms.</td></tr>\n    <tr><td>Type-level differences</td><td>Systematic Reviews involve larger teams (median 7–8 authors) compared to Case Reports (median 4–5), consistent with the methodological demands of evidence synthesis requiring broader expertise.</td></tr>\n  </table>\n</div>\n\n<!-- ═══════════ SECTION 6: KEY TAKEAWAYS ═══════════ -->\n<div class=\"section\" id=\"key-takeaways\">\n  <h2>6. Key Takeaways &amp; Strategic Implications</h2>\n  <p class=\"section-obj\">Synthesis of the most important findings into actionable insights for research policy, funding prioritization, and institutional strategy.</p>\n\n  <ol class=\"takeaway-list\">\n    <li>\n      <span class=\"takeaway-num\">1</span>\n      <div>\n        <strong>Open Access has crossed the 65% threshold and is still rising.</strong>\n        <span class=\"tag tag-policy\">Policy</span>\n        <p style=\"margin-top:4px;font-size:14px;color:var(--text-secondary);\">\n          The OA rate reached 65.1% overall and 71.1% in Q1 2026. This has direct implications for subscription budget modeling, repository infrastructure investment, and compliance with funder OA mandates. Institutions should plan for an OA-majority publishing environment by 2027.\n        </p>\n      </div>\n    </li>\n    <li>\n      <span class=\"takeaway-num\">2</span>\n      <div>\n        <strong>China's research output leads globally, but OA adoption lags — a strategic gap.</strong>\n        <span class=\"tag tag-funding\">Funding</span>\n        <p style=\"margin-top:4px;font-size:14px;color:var(--text-secondary);\">\n          China produces 19.5% of indexed output but has one of the lower OA rates (~60%). As international funders increasingly require OA, this gap represents both a challenge for Chinese researchers and a lever for publishers and policymakers to accelerate OA adoption through targeted mandates.\n        </p>\n      </div>\n    </li>\n    <li>\n      <span class=\"takeaway-num\">3</span>\n      <div>\n        <strong>Environmental health and biodiversity research show the fastest normalized growth.</strong>\n        <span class=\"tag tag-watch\">Emerging</span>\n        <p style=\"margin-top:4px;font-size:14px;color:var(--text-secondary);\">\n          Keywords related to air pollution, animal biodiversity, and environmental monitoring are growing rapidly in normalized rate. This aligns with the One Health framework and suggests funding agencies should anticipate increased grant applications at the intersection of environmental science and biomedicine.\n        </p>\n      </div>\n    </li>\n    <li>\n      <span class=\"takeaway-num\">4</span>\n      <div>\n        <strong>Pandemic-era research is normalizing — COVID-19 remains #1 but is decelerating.</strong>\n        <span class=\"tag tag-funding\">Funding</span>\n        <p style=\"margin-top:4px;font-size:14px;color:var(--text-secondary);\">\n          COVID-19 is still the single largest major topic but its normalized publication rate dropped from 9.4/1K to 6.8/1K. Funding strategists should plan for the transition from emergency COVID funding toward sustained pandemic-preparedness and long-COVID research programs.\n        </p>\n      </div>\n    </li>\n    <li>\n      <span class=\"takeaway-num\">5</span>\n      <div>\n        <strong>Computational methods are diffusing across fields.</strong>\n        <span class=\"tag tag-watch\">Emerging</span>\n        <p style=\"margin-top:4px;font-size:14px;color:var(--text-secondary);\">\n          \"Molecular Dynamics Simulation\" (+5.0/1K), \"Signal Processing, Computer-Assisted\" (+6.4/1K), and \"Algorithms\" (+2.8/1K) are among the fastest-growing keywords. This signals that computational and AI/ML methods are becoming embedded across biomedical research, not siloed in bioinformatics. Investment in computational research infrastructure and training should be a cross-cutting priority.\n        </p>\n      </div>\n    </li>\n    <li>\n      <span class=\"takeaway-num\">6</span>\n      <div>\n        <strong>Collaboration intensity is stable but geographically patterned.</strong>\n        <span class=\"tag tag-policy\">Policy</span>\n        <p style=\"margin-top:4px;font-size:14px;color:var(--text-secondary);\">\n          The median of 6 authors per paper has held steady year-over-year. Western countries show systematically larger teams (median 7–8) than Asian countries (median 5–6). This may affect research impact metrics and should be considered when benchmarking institutional collaboration KPIs.\n        </p>\n      </div>\n    </li>\n    <li>\n      <span class=\"takeaway-num\">7</span>\n      <div>\n        <strong>The publishing landscape is highly distributed — no single journal dominates.</strong>\n        <span class=\"tag tag-policy\">Policy</span>\n        <p style=\"margin-top:4px;font-size:14px;color:var(--text-secondary);\">\n          The top 20 journals account for only ~15% of output. This fragmentation has implications for literature surveillance, evidence synthesis, and collection development strategies. Tools and policies designed around a small set of \"core journals\" will miss the majority of relevant research.\n        </p>\n      </div>\n    </li>\n  </ol>\n</div>\n\n<!-- ═══════════ FOOTER ═══════════ -->\n<div class=\"footer\">\n  <p><strong>Biomedical Research Landscape 2024–2026</strong> | Trend Analysis Report | May 2026</p>\n  <p>Data source: NCBI PubMed via Kaggle (kanchana1990/biomedical-research-abstracts-20242026)</p>\n  <p class=\"data-note\">\n    <strong>Limitations:</strong> This analysis uses a dataset of 4,886 records (the source brief reference of 126,832 records represents the full upstream dataset; the local file contains a subset). Temporal comparisons are normalized to account for indexing lag skewing toward 2024. 15.4% of records have unknown publication months and are excluded from monthly analyses. 47.1% lack MeSH major topic assignments. Country names were normalized from 1,126 raw variants to 1,116 unique values; some inconsistency may remain.\n  </p>\n</div>\n\n</div><!-- /container -->\n\n<!-- ═══════════ CHARTS (inline JS) ═══════════ -->\n<script>\n// ── Color palette ──\nconst BLUE = '#2563eb', BLUE_LIGHT = '#93c5fd';\nconst COLORS10 = ['#2563eb','#16a34a','#d97706','#dc2626','#7c3aed','#0891b2','#be185d','#65a30d','#ea580c','#4f46e5'];\n\n// ── Section 1: Yearly bars ──\nnew Chart(document.getElementById('chart-yearly'), {\n  type: 'bar',\n  data: {\n    labels: ['2024','2025','2026'],\n    datasets: [{\n      label: 'Publications',\n      data: [3924, 737, 225],\n      backgroundColor: [BLUE, '#60a5fa', '#93c5fd'],\n      borderRadius: 6,\n    }]\n  },\n  options: {\n    responsive: true,\n    plugins: {\n      legend: { display: false },\n      tooltip: { callbacks: { label: ctx => `${ctx.raw.toLocaleString()} publications (${(ctx.raw/4886*100).toFixed(1)}%)` } }\n    },\n    scales: { y: { beginAtZero: true, title: { display: true, text: 'Publications' } } }\n  }\n});\n\n// ── Section 1: Monthly line ──\nconst monthlyLabels = [\"Jan-2024\",\"Feb-2024\",\"Mar-2024\",\"Apr-2024\",\"May-2024\",\"Jun-2024\",\"Jul-2024\",\"Aug-2024\",\"Sep-2024\",\"Oct-2024\",\"Nov-2024\",\"Dec-2024\",\"Jan-2025\",\"Feb-2025\",\"Mar-2025\",\"Apr-2025\",\"May-2025\",\"Jun-2025\",\"Jul-2025\",\"Aug-2025\",\"Sep-2025\",\"Oct-2025\",\"Nov-2025\",\"Dec-2025\",\"Jan-2026\",\"Feb-2026\",\"Mar-2026\"];\nconst monthlyData2024 = [1660,479,497,303,145,158,128,78,101,70,74,153];\nconst monthlyData2025 = [64,34,35,25,26,20,14,7,13,4,5,12];\nconst monthlyData2026 = [22,3,2,0,0,0,0,0,0,0,0,0];\n\nnew Chart(document.getElementById('chart-monthly'), {\n  type: 'line',\n  data: {\n    labels: monthlyLabels,\n    datasets: [\n      { label: '2024', data: monthlyData2024, borderColor: BLUE, backgroundColor: 'transparent', tension: 0.3, pointRadius: 2 },\n      { label: '2025', data: monthlyData2025, borderColor: '#16a34a', backgroundColor: 'transparent', tension: 0.3, pointRadius