dies\",\"Infant\",\"Time Factors\",\"Magnetic Resonance Imaging\",\"Prospective Studies\",\"Immunohistochemistry\",\"Disease Models, Animal\",\"Algorithms\",\"Infant, Newborn\"];\nconst topKwCounts = [892,792,596,589,272,223,169,93,91,89,87,84,82,81,78,78,73,72,70,69,65,59,59,58,56,56,55,53,53,53];\nnew Chart(document.getElementById('chart-keywords-top'), {\n  type: 'bar',\n  data: {\n    labels: topKw,\n    datasets: [{\n      label: 'Frequency',\n      data: topKwCounts,\n      backgroundColor: BLUE,\n      borderRadius: 3,\n    }]\n  },\n  options: {\n    indexAxis: 'y',\n    responsive: true,\n    plugins: { legend: { display: false } },\n    scales: { x: { beginAtZero: true, title: { display: true, text: 'Frequency' } } }\n  }\n});\n\n// ── Section 4: OA monthly ──\nconst oaMonthlyVals = [65.4,66.2,67.6,65.7,66.2,62.7,64.8,71.8,61.4,62.9,60.8,62.1,70.3,61.8,68.6,72.0,61.5,70.0,64.3,71.4,69.2,75.0,80.0,50.0,77.3,100.0,50.0];\nnew Chart(document.getElementById('chart-oa-monthly'), {\n  type: 'line',\n  data: {\n    labels: monthlyLabels,\n    datasets: [{\n      label: 'OA Rate (%)',\n      data: oaMonthlyVals,\n      borderColor: '#16a34a',\n      backgroundColor: 'rgba(22,163,74,0.1)',\n      fill: true,\n      tension: 0.3,\n      pointRadius: 2,\n    }]\n  },\n  options: {\n    responsive: true,\n    plugins: {\n      legend: { display: false },\n      tooltip: { callbacks: { label: ctx => `OA Rate: ${ctx.raw}%` } }\n    },\n    scales: {\n      x: { ticks: { maxTicksLimit: 14, font: { size: 10 } } },\n      y: { min: 40, max: 100, title: { display: true, text: 'OA Rate (%)' } }\n    }\n  }\n});\n\n// ── Section 4: OA by year ──\nnew Chart(document.getElementById('chart-oa-yearly'), {\n  type: 'bar',\n  data: {\n    labels: ['2024','2025','2026 (Q1)'],\n    datasets: [\n      { label: 'Open Access', data: [2524,494,160], backgroundColor: '#16a34a', borderRadius: 6, stack: 'oa' },\n      { label: 'Closed Access', data: [1400,243,65], backgroundColor: '#e5e7eb'